with joined as (select e.*, p.country, p.credit_limit from subscriptions e inner join customers p on e.customer_id = p.id), with_windows as (select id, customer_id, plan, end_date, status, country, max(monthly_fee) over w_grp as last4_max_monthly_fee, sum(monthly_fee) over w_grp as last4_sum_monthly_fee, avg(monthly_fee) over w_grp as last4_avg_monthly_fee, min(monthly_fee) over w_grp as last4_min_monthly_fee from joined window w_grp as (partition by plan order by end_date, id rows between 3 preceding and current row)), enriched as (select *, lag(last4_min_monthly_fee) over w_running as prev_last4_min_monthly_fee, lead(last4_min_monthly_fee) over w_running as next_last4_min_monthly_fee, lead(last4_avg_monthly_fee) over w_running as next_last4_avg_monthly_fee, row_number() over w_running as event_seq from with_windows where month(end_date) in (3, 9, 12) window w_running as (partition by country, customer_id order by last4_avg_monthly_fee, id)), enriched_subscriptions as (select *, sum(prev_last4_min_monthly_fee) over (partition by status order by last4_sum_monthly_fee, id rows between unbounded preceding and current row) as running_prev_last4_min_monthly_fee, rank() over (partition by country order by last4_sum_monthly_fee desc nulls first) as last4_sum_monthly_fee_rank, sum(last4_min_monthly_fee) over (partition by country order by prev_last4_min_monthly_fee, id rows between unbounded preceding and current row) as cumulative_last4_min_monthly_fee, row_number() over (partition by country order by end_date desc, id) as row_seq from enriched) select id, customer_id, metric, val from (select id, customer_id, last4_avg_monthly_fee, last4_sum_monthly_fee, prev_last4_min_monthly_fee from enriched_subscriptions) src unpivot (val for metric in (last4_avg_monthly_fee, last4_sum_monthly_fee, prev_last4_min_monthly_fee)) long_rows;
